import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the optimized CUDA kernel with register blocking
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define BLOCK_SIZE 8  // 8x8 threads per block (each thread computes 4x4 output)

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Block indices
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread indices within block
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Each thread computes a 4x4 block of C
    float c[4][4] = {{0.0f}};

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tile from A into shared memory (coalesced)
        int row = by * TILE_SIZE + ty * 4;
        int col = t * TILE_SIZE + tx * 4;

        if (row < N && col < N) {
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    int idx = (row + i) * N + col + j;
                    if (col + j < N) {
                        As[ty * 4 + i][tx * 4 + j] = A[idx];
                    } else {
                        As[ty * 4 + i][tx * 4 + j] = 0.0f;
                    }
                }
            }
        } else {
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    As[ty * 4 + i][tx * 4 + j] = 0.0f;
                }
            }
        }

        // Load tile from B into shared memory (coalesced)
        row = t * TILE_SIZE + ty * 4;
        col = bx * TILE_SIZE + tx * 4;

        if (row < N && col < N) {
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    int idx = (row + i) * N + col + j;
                    if (row + i < N) {
                        Bs[ty * 4 + i][tx * 4 + j] = B[idx];
                    } else {
                        Bs[ty * 4 + i][tx * 4 + j] = 0.0f;
                    }
                }
            }
        } else {
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    Bs[ty * 4 + i][tx * 4 + j] = 0.0f;
                }
            }
        }

        __syncthreads();

        // Compute partial sums using register blocking
        for (int k = 0; k < TILE_SIZE; k++) {
            float a_reg[4], b_reg[4];

            // Load 4 elements from As and Bs into registers
            for (int i = 0; i < 4; i++) {
                a_reg[i] = As[ty * 4 + i][k];
            }
            for (int j = 0; j < 4; j++) {
                b_reg[j] = Bs[k][tx * 4 + j];
            }

            // Accumulate products
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    c[i][j] += a_reg[i] * b_reg[j];
                }
            }
        }

        __syncthreads();
    }

    // Write 4x4 block to global memory
    int row_start = by * TILE_SIZE + ty * 4;
    int col_start = bx * TILE_SIZE + tx * 4;

    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            if (row_start + i < N && col_start + j < N) {
                int idx = (row_start + i) * N + col_start + j;
                C[idx] = c[i][j];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Check tensor dimensions
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions mismatch");

    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    // Set grid and block dimensions
    dim3 blockSize(BLOCK_SIZE, BLOCK_SIZE);
    dim3 gridSize((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    // Launch kernel
    matmul_kernel<<<gridSize, blockSize>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

